window.DD_ENTRIES = [
  {"id":"rohn-01","au":"rohn","s":"Philosophy","a":"I set the sail rather than argue with the wind; my thinking, not my circumstances, decides where I land.","p":"Write down one belief you hold about money, work or people, and ask whether it has ever produced a result you actually wanted.","k":["mindset","responsibility","circumstances","set of the sail"],"src":"After the 'set of the sail' teaching"},
  {"id":"rohn-02","au":"rohn","s":"Philosophy","a":"I own my results completely — no blaming the weather, the market, or anyone else in the room.","p":"Take one complaint you made this week and rewrite it as a decision only you can make.","k":["responsibility","ownership","blame","accountability"],"src":"After Rohn on personal responsibility"},
  {"id":"rohn-03","au":"rohn","s":"Philosophy","a":"What I believe shapes how I feel, how I feel shapes what I do, and what I do shows up in what I have.","p":"Trace one result you're unhappy with backwards — through activity, through attitude — until you find the belief it started from.","k":["philosophy","attitude","activity","results","five major pieces"],"src":"After The Five Major Pieces to the Life Puzzle"},
  {"id":"rohn-04","au":"rohn","s":"Philosophy","a":"If I don't design a plan for my life, I'll spend it inside somebody else's.","p":"Block one hour this week with a blank page and write what you want the next three years to look like.","k":["life plan","design","intention","drift"],"src":"After Rohn on designing your own life plan"},
  {"id":"rohn-05","au":"rohn","s":"Philosophy","a":"Change starts with me, not with my conditions; when I become different, everything downstream changes too.","p":"Name the one habit that, if it changed, would change the most other things — and start it today.","k":["change","growth","becoming","transformation"],"src":"After 'for things to change, you have to change'"},
  {"id":"rohn-06","au":"rohn","s":"Attitude","a":"I refuse to beat myself with my past; I take the lesson and leave the weight.","p":"Write down one failure, then write the single sentence you learned from it, and close the book on the rest.","k":["past","regret","forgiveness","learning"],"src":"After Rohn on how you feel about the past"},
  {"id":"rohn-07","au":"rohn","s":"Attitude","a":"I stand guard at the door of my mind and choose deliberately what gets in.","p":"Cut one input today — a feed, a show, a conversation — that reliably leaves you smaller.","k":["input","media","guard","mindset"],"src":"After 'stand guard at the door of your mind'"},
  {"id":"rohn-08","au":"rohn","s":"Attitude","a":"Gratitude is a discipline, not a mood; I practise it hardest on the days it doesn't arrive on its own.","p":"List three things you would genuinely miss if they vanished tonight.","k":["gratitude","discipline","mood","perspective"],"src":"After Rohn on attitude and appreciation"},
  {"id":"rohn-09","au":"rohn","s":"Attitude","a":"I hold a good opinion of other people, because it takes everybody else to make a market.","p":"Say one specific, true, appreciative thing to someone today without being asked.","k":["people","generosity","relationships","market"],"src":"After Rohn on how you feel about everybody else"},
  {"id":"rohn-10","au":"rohn","s":"Attitude","a":"How I feel about the future is a choice, and I choose expectancy over dread.","p":"Write one sentence describing a future you'd be glad to walk into, and read it again tomorrow morning.","k":["optimism","future","expectancy","fear"],"src":"After Rohn on how you feel about the future"},
  {"id":"rohn-11","au":"rohn","s":"Discipline","a":"I pay in ounces now so I don't pay in tons later; discipline is simply the cheaper of the two pains.","p":"Identify the task you're avoiding and give it the next twenty minutes.","k":["discipline","regret","pain","procrastination"],"src":"After the two pains: discipline and regret"},
  {"id":"rohn-12","au":"rohn","s":"Discipline","a":"Success is a handful of small things done every day, not one heroic thing done once.","p":"Pick a single daily action you could sustain for ninety days, and do it today.","k":["habits","consistency","daily","small things"],"src":"After 'a few simple disciplines practised every day'"},
  {"id":"rohn-13","au":"rohn","s":"Discipline","a":"Motivation gets me moving; habit is what keeps me moving once the feeling wears off.","p":"Attach the habit you want to one you already do without thinking.","k":["motivation","habit","momentum","routine"],"src":"After Rohn on motivation versus habit"},
  {"id":"rohn-14","au":"rohn","s":"Discipline","a":"Every disciplined act pays me twice — in the result, and in who I become while earning it.","p":"Notice one compounding benefit from a discipline you already keep.","k":["reward","compounding","character","effort"],"src":"After 'for every disciplined effort there is a multiple reward'"},
  {"id":"rohn-15","au":"rohn","s":"Discipline","a":"I don't wish the work were easier; I get better at the work.","p":"Name one skill that would make your hardest task routine, and spend thirty minutes on it.","k":["skill","difficulty","growth","competence"],"src":"After 'don't wish it were easier, wish you were better'"},
  {"id":"rohn-16","au":"rohn","s":"Self-Education","a":"School gave me a living; what I read after school decides the rest.","p":"Start a book today that someone you admire would recommend.","k":["reading","books","education","learning"],"src":"After Rohn on formal versus self-education"},
  {"id":"rohn-17","au":"rohn","s":"Self-Education","a":"I keep a journal, because a life worth living is worth the trouble of recording.","p":"Write half a page tonight: what happened, what it cost, what it taught you.","k":["journal","reflection","record","writing"],"src":"After Rohn on keeping a journal"},
  {"id":"rohn-18","au":"rohn","s":"Self-Education","a":"I learn from other people's experience so I don't have to buy every lesson at full price.","p":"Ask someone who has already done the thing you're attempting what they'd do differently.","k":["mentors","experience","advice","shortcuts"],"src":"After Rohn on not learning only from your own experience"},
  {"id":"rohn-19","au":"rohn","s":"Self-Education","a":"My success rarely climbs higher than my personal development, so I work on the developer.","p":"Spend thirty minutes on yourself before you spend eight hours on your job.","k":["personal development","self-improvement","ceiling","growth"],"src":"After 'work harder on yourself than you do on your job'"},
  {"id":"rohn-20","au":"rohn","s":"Self-Education","a":"I'd rather be a student than be right; curiosity outperforms certainty over any long stretch.","p":"Find one strongly held opinion and go read the best argument against it.","k":["curiosity","humility","learning","open mind"],"src":"After Rohn on lifelong learning"},
  {"id":"rohn-21","au":"rohn","s":"Goals","a":"The real value of a goal isn't what I get; it's who I have to become to get it.","p":"Write beside your biggest goal the kind of person who achieves it — then start being that person.","k":["goals","becoming","achievement","character"],"src":"After 'what it makes of you is the greater value'"},
  {"id":"rohn-22","au":"rohn","s":"Goals","a":"Vague wishes produce vague results; I write mine down where I can be held to them.","p":"Convert one wish into a written goal with a date attached.","k":["clarity","writing","specificity","wishes"],"src":"After Rohn on the art of setting goals"},
  {"id":"rohn-23","au":"rohn","s":"Goals","a":"I set goals big enough to be interesting and near enough to be believed.","p":"Set one goal for this month and one for the next five years, on the same page.","k":["ambition","horizon","planning","belief"],"src":"After Rohn on long- and short-range goals"},
  {"id":"rohn-24","au":"rohn","s":"Goals","a":"Without urgency, wanting something is just a hobby.","p":"Give one goal a deadline this week and tell someone about it.","k":["urgency","deadlines","desire","action"],"src":"After 'without a sense of urgency, desire loses its value'"},
  {"id":"rohn-25","au":"rohn","s":"Goals","a":"I review my goals often enough that they steer me rather than decorate a drawer.","p":"Put a recurring fifteen minutes in your calendar to reread what you're aiming at.","k":["review","focus","direction","consistency"],"src":"After Rohn on reviewing goals"},
  {"id":"rohn-26","au":"rohn","s":"Time","a":"Either I run the day or the day runs me, so I decide before the noise starts.","p":"Choose tomorrow's three most important tasks tonight, before you sleep.","k":["time management","planning","priorities","mornings"],"src":"After 'either you run the day or the day runs you'"},
  {"id":"rohn-27","au":"rohn","s":"Time","a":"Days are expensive: every one I spend is one I no longer have to spend.","p":"Count how many hours today went to something you'd defend out loud.","k":["time","cost","awareness","waste"],"src":"After 'days are expensive'"},
  {"id":"rohn-28","au":"rohn","s":"Time","a":"I refuse to spend major time on minor things.","p":"Find the lowest-value task on today's list and delete it rather than do it.","k":["priorities","focus","trivia","elimination"],"src":"After 'don't spend major time on minor things'"},
  {"id":"rohn-29","au":"rohn","s":"Time","a":"I give full attention to whoever is in front of me — it's one of the better gifts I have to hand out.","p":"Put the phone face-down for the length of one conversation today.","k":["attention","presence","relationships","focus"],"src":"After Rohn on the gift of attention"},
  {"id":"rohn-30","au":"rohn","s":"Time","a":"Busy is not the same as productive; I measure results, not motion.","p":"At day's end, write what actually moved forward — not what you touched.","k":["productivity","busyness","results","measurement"],"src":"After Rohn on activity and results"},
  {"id":"rohn-31","au":"rohn","s":"Sowing & Reaping","a":"I get paid for the value I bring, so I spend my energy becoming more valuable.","p":"Ask what your work would be worth if it were twice as good, then do one thing to close that gap.","k":["value","marketplace","worth","income"],"src":"After 'we get paid for bringing value to the marketplace'"},
  {"id":"rohn-32","au":"rohn","s":"Sowing & Reaping","a":"Nobody harvests what they never planted, so I stop waiting and start sowing.","p":"Plant one seed today — a call, an application, a first draft — with no promise of immediate return.","k":["sowing","reaping","cause and effect","patience"],"src":"After the law of sowing and reaping"},
  {"id":"rohn-33","au":"rohn","s":"Sowing & Reaping","a":"The harvest is honest: it reports exactly what I did, not what I intended.","p":"Look at one disappointing result and name the input that produced it, without excuses.","k":["results","honesty","feedback","accountability"],"src":"After Rohn on the harvest as a report card"},
  {"id":"rohn-34","au":"rohn","s":"Sowing & Reaping","a":"I sow generously, because the size of the harvest follows the size of the planting.","p":"Do more than the minimum on one task today, purely because you chose to.","k":["generosity","effort","abundance","extra mile"],"src":"After the law of sowing and reaping"},
  {"id":"rohn-35","au":"rohn","s":"Sowing & Reaping","a":"Some of what I plant won't come up, and I plant anyway — that's the arithmetic of every harvest.","p":"Send the message, make the pitch, take the shot you've been rationing.","k":["risk","rejection","persistence","numbers"],"src":"After Rohn on the parable of the sower"},
  {"id":"rohn-36","au":"rohn","s":"Seasons & Adversity","a":"I can't change the seasons, but I can change the person who has to meet them.","p":"Name which season you're in right now, and what that season is actually asking of you.","k":["seasons","adversity","change","self"],"src":"After 'you cannot change the seasons, but you can change yourself'"},
  {"id":"rohn-37","au":"rohn","s":"Seasons & Adversity","a":"Winters arrive on schedule, so I prepare in summer instead of hoping in autumn.","p":"Build one reserve today — savings, a skill, a relationship — for a winter you can't yet see.","k":["winter","preparation","resilience","foresight"],"src":"After the Ant Philosophy: think winter all summer"},
  {"id":"rohn-38","au":"rohn","s":"Seasons & Adversity","a":"In the cold I remind myself this doesn't last, and I'm ready to move on the first warm day.","p":"Write down the first thing you'll do when the current hard stretch breaks.","k":["hope","patience","endurance","recovery"],"src":"After the Ant Philosophy: think summer all winter"},
  {"id":"rohn-39","au":"rohn","s":"Seasons & Adversity","a":"When something blocks my way I go over, under, or around — but I don't stop looking for the way.","p":"List three alternative routes to the goal you've decided is blocked.","k":["persistence","obstacles","ant philosophy","resourcefulness"],"src":"After the Ant Philosophy: ants never quit"},
  {"id":"rohn-40","au":"rohn","s":"Seasons & Adversity","a":"Spring is short and it doesn't wait; while the ground is soft, I plant.","p":"Act on the opportunity you've been 'thinking about' before this week ends.","k":["opportunity","timing","urgency","spring"],"src":"After 'learn how to take advantage of the spring'"},
  {"id":"rohn-41","au":"rohn","s":"Associations","a":"I become the average of the company I keep, so I choose my circle on purpose.","p":"List the five people you spend the most time with and ask honestly where each is taking you.","k":["circle","influence","friends","average"],"src":"After 'the average of the five people you spend the most time with'"},
  {"id":"rohn-42","au":"rohn","s":"Associations","a":"I don't join easy crowds; I go where the standard is high enough to stretch me.","p":"Find one room — a group, a class, a team — where you're not the most capable person present.","k":["standards","crowds","growth","environment"],"src":"After 'don't join an easy crowd, you won't grow'"},
  {"id":"rohn-43","au":"rohn","s":"Associations","a":"Some people I spend less time with, some more, and some not at all — that's a decision, not a verdict.","p":"Reduce time with one relationship that consistently costs more than it gives.","k":["boundaries","relationships","choice","disassociation"],"src":"After Rohn on association and disassociation"},
  {"id":"rohn-44","au":"rohn","s":"Associations","a":"I look for people who've already walked where I'm heading, and I ask them questions.","p":"Reach out to one person ahead of you and ask for twenty minutes.","k":["mentors","guidance","questions","network"],"src":"After Rohn on mentorship, and his own mentor J. Earl Shoaff"},
  {"id":"rohn-45","au":"rohn","s":"Associations","a":"I try to be, for somebody else, the influence I was lucky enough to receive.","p":"Offer specific help to one person coming up behind you.","k":["mentoring","service","giving back","leadership"],"src":"After Rohn on passing the philosophy on"},
  {"id":"rohn-46","au":"rohn","s":"Money","a":"I live on seventy percent of what I earn and give the other thirty a job: giving, investing, saving.","p":"Work out what seventy percent of your take-home actually is, and what the rest is currently doing.","k":["70/30 rule","budgeting","saving","money"],"src":"After the 70/30 rule"},
  {"id":"rohn-47","au":"rohn","s":"Money","a":"Wages keep me; what I build for myself is what makes me.","p":"Spend one hour this week on something you own rather than something you're paid for.","k":["profits","wages","ownership","side project"],"src":"After 'profits are better than wages'"},
  {"id":"rohn-48","au":"rohn","s":"Money","a":"I give first, before it's comfortable — generosity is a habit, not a byproduct of surplus.","p":"Give something away this week at a scale you actually notice.","k":["giving","generosity","charity","habit"],"src":"After the 70/30 rule and Rohn on giving"},
  {"id":"rohn-49","au":"rohn","s":"Money","a":"Money follows value, so I stop asking to be paid more and start becoming worth more.","p":"Identify the single skill that would most raise your market value, and book time for it.","k":["value","earnings","skills","worth"],"src":"After Rohn on value and the marketplace"},
  {"id":"rohn-50","au":"rohn","s":"Money","a":"If I can't manage a little well, more won't fix it — capability comes before capacity.","p":"Track every pound you spend for the next seven days without changing anything else.","k":["management","discipline","tracking","capability"],"src":"After Rohn on becoming a millionaire before you keep the million"},
  {"id":"rohn-51","au":"rohn","s":"Communication","a":"I practise how I speak on ordinary days so the skill is there on the day it matters.","p":"Say one thing today more clearly and more briefly than you normally would.","k":["communication","practice","clarity","speaking"],"src":"After Rohn on practising your communication skills"},
  {"id":"rohn-52","au":"rohn","s":"Communication","a":"I aim to be strong without being rude, and kind without being weak.","p":"Deliver one honest piece of feedback today with more care than usual.","k":["leadership","strength","kindness","balance"],"src":"After the challenge of leadership passage"},
  {"id":"rohn-53","au":"rohn","s":"Communication","a":"Leadership is the decision to be more than average — first in myself, then for anybody else.","p":"Raise your own standard on one task before you ask anyone else to raise theirs.","k":["leadership","standards","example","average"],"src":"After Rohn on leadership as the challenge to be more than average"},
  {"id":"rohn-54","au":"rohn","s":"Communication","a":"I lead by attraction rather than pressure; people follow what they'd quite like to become.","p":"Do the thing you'd want your team, your family or your friends to do, without mentioning that you did it.","k":["example","influence","attraction","integrity"],"src":"After Rohn on leadership by example"},
  {"id":"rohn-55","au":"rohn","s":"Communication","a":"I listen for what the other person actually needs, not for my turn to talk.","p":"In your next conversation, ask two questions before you make a statement.","k":["listening","questions","empathy","conversation"],"src":"After Rohn on the gift of attention"},
  {"id":"rohn-56","au":"rohn","s":"Lifestyle & Health","a":"I take care of my body; it's the only place I have to live.","p":"Move for thirty minutes today, at whatever intensity you'll actually repeat tomorrow.","k":["health","body","exercise","care"],"src":"After 'take care of your body, it's the only place you have to live'"},
  {"id":"rohn-57","au":"rohn","s":"Lifestyle & Health","a":"Wealth with no life to spend it on is just a number; I design the living as carefully as the earning.","p":"Put one thing in the diary this month that exists purely to be enjoyed.","k":["lifestyle","balance","enjoyment","design"],"src":"After Rohn on lifestyle as the art of living well"},
  {"id":"rohn-58","au":"rohn","s":"Lifestyle & Health","a":"I make room for what feeds me — music, art, travel, good conversation — because a life needs texture.","p":"Book, borrow or plan one cultural thing you've been meaning to get to.","k":["culture","art","travel","texture"],"src":"After Rohn on culture and sophistication"},
  {"id":"rohn-59","au":"rohn","s":"Lifestyle & Health","a":"Sharing what I've gathered is rather the point of gathering it.","p":"Pass on something you know to someone who could use it, today.","k":["sharing","generosity","contribution","purpose"],"src":"After Rohn on sharing your bounty"},
  {"id":"rohn-60","au":"rohn","s":"Lifestyle & Health","a":"I want to be remembered for the character I built, not the fingerprints I was issued.","p":"Name the one trait you'd want said about you, and do one thing today that earns it.","k":["character","legacy","integrity","identity"],"src":"After Rohn on character as something you form"},
  {"id":"bryant-01","au":"bryant","s":"Financial Dignity","a":"I treat financial literacy as a civil rights matter, because not knowing the rules of money is how people stay locked out.","p":"Learn one financial term properly today — APR, compounding, amortisation — and explain it to somebody else.","k":["financial literacy","civil rights","knowledge","exclusion"],"src":"After Bryant on financial literacy as the civil rights issue of this generation"},
  {"id":"bryant-02","au":"bryant","s":"Financial Dignity","a":"Civil rights got me the seat; silver rights are about being able to afford the meal.","p":"Name one economic goal that would change your family's options, and write the first step under it.","k":["silver rights","economics","opportunity","ownership"],"src":"After Bryant's “from civil rights to silver rights” framing"},
  {"id":"bryant-03","au":"bryant","s":"Financial Dignity","a":"My credit score is not a judgment on my worth; it is a number I can move with information and time.","p":"Check your credit report this week and fix or dispute one thing on it.","k":["credit","score","repair","agency"],"src":"After Bryant and the 700 Credit Score Club"},
  {"id":"bryant-04","au":"bryant","s":"Financial Dignity","a":"Poverty is not only a shortage of money; it is a shortage of confidence, role models and working information.","p":"Identify which of those four you are shortest on right now, and address that one first.","k":["poverty","confidence","information","mindset"],"src":"After Bryant on redefining poverty and wealth"},
  {"id":"bryant-05","au":"bryant","s":"Financial Dignity","a":"I invest for the long term rather than speculate for the thrill; the two only look alike from a distance.","p":"Before your next financial decision, ask whether you're buying an asset or buying excitement.","k":["investing","speculation","patience","discipline"],"src":"After Financial Literacy for All"},
  {"id":"bryant-06","au":"bryant","s":"Love Leadership","a":"Loss made me a leader; there is no depth without some legitimate suffering behind it.","p":"Write down what one hard season actually taught you that comfort could not have.","k":["loss","leadership","suffering","depth"],"src":"After the first law in Love Leadership: loss creates leaders"},
  {"id":"bryant-07","au":"bryant","s":"Love Leadership","a":"Fear can start a movement but it cannot sustain one; only respect keeps people in the room.","p":"Find one place where you're using pressure, and replace it with a reason.","k":["fear","respect","motivation","leadership"],"src":"After the second law in Love Leadership: fear fails"},
  {"id":"bryant-08","au":"bryant","s":"Love Leadership","a":"Doing right by people is not the opposite of doing well; over a long enough horizon it is the mechanism.","p":"Choose the option that serves the other party best in one negotiation this month, and watch what returns.","k":["ethics","profit","trust","long game"],"src":"After the third law in Love Leadership: love makes money"},
  {"id":"bryant-09","au":"bryant","s":"Love Leadership","a":"When I open up first, other people stop performing — vulnerability is leverage, not exposure.","p":"Admit one thing you don't know in a meeting where you'd normally bluff.","k":["vulnerability","honesty","openness","power"],"src":"After the fourth law in Love Leadership: vulnerability is power"},
  {"id":"bryant-10","au":"bryant","s":"Love Leadership","a":"I give before I'm asked and before I'm certain of the return, because that is the whole trick.","p":"Do one useful thing for someone this week with no expectation attached.","k":["giving","generosity","reciprocity","service"],"src":"After the fifth law in Love Leadership: giving is getting"},
  {"id":"bryant-11","au":"bryant","s":"Mindset","a":"I am moving from survivor to thriver to winner, and I refuse to mistake the first stage for my ceiling.","p":"Name which stage you're actually in, and the one behaviour that belongs to the next one.","k":["mindset","survivor","thriver","winner"],"src":"After Up From Nothing"},
  {"id":"bryant-12","au":"bryant","s":"Mindset","a":"I believed I was a winner before I had won anything; that order is not arrogance, it's sequence.","p":"Do one thing today in the manner of the person you intend to become.","k":["self-belief","identity","confidence","sequence"],"src":"After Up From Nothing on believing before winning"},
  {"id":"bryant-13","au":"bryant","s":"Mindset","a":"My self-esteem is infrastructure; without it every other resource leaks away.","p":"Keep one small promise to yourself today, purely to prove your own word is good.","k":["self-esteem","promises","integrity","foundation"],"src":"After the Five Pillars of Success"},
  {"id":"bryant-14","au":"bryant","s":"Mindset","a":"I don't wait for the system to be fair before I learn how it works.","p":"Learn one rule of a system that has cost you — tax, credit, hiring — and use it this month.","k":["systems","pragmatism","knowledge","agency"],"src":"After Bryant on operating inside an imperfect economy"},
  {"id":"bryant-15","au":"bryant","s":"Community & Role Models","a":"Somebody once walked into my classroom and showed me a life I didn't know existed; I try to be that for someone else.","p":"Offer twenty minutes to one young person who has never met anyone doing your job.","k":["role models","mentoring","visibility","service"],"src":"After Bryant's account of the banker who visited his school"},
  {"id":"bryant-16","au":"bryant","s":"Community & Role Models","a":"You cannot become what you have never seen, so I make sure other people can see it.","p":"Talk publicly about how you actually got where you are, including the unglamorous parts.","k":["representation","example","aspiration","honesty"],"src":"After the Five Pillars of Success: supportive role models"},
  {"id":"bryant-17","au":"bryant","s":"Community & Role Models","a":"Rebuilding one street is more useful than diagnosing a whole country.","p":"Pick one street, block or institution near you and do something concrete for it.","k":["community","local","action","practicality"],"src":"After Operation HOPE's on-the-ground model"},
  {"id":"bryant-18","au":"bryant","s":"Community & Role Models","a":"I want a capitalism that works for more people, so I aim to widen the ladder rather than only climb it.","p":"Find one way your work could open a door for somebody outside your usual circle.","k":["capitalism","inclusion","access","ladder"],"src":"After How the Poor Can Save Capitalism and Capitalism For All"},
  {"id":"frankl-01","au":"frankl","s":"Meaning","a":"Between what happens to me and how I answer it, there is a space — and that space is mine.","p":"Notice one moment today where you paused before reacting, and lengthen the next one.","k":["freedom","response","attitude","choice"],"src":"After Frankl on the last of the human freedoms"},
  {"id":"frankl-02","au":"frankl","s":"Meaning","a":"When I stop asking what I want from life and start answering what life is asking of me, the question gets solvable.","p":"Ask what your current situation is actually requiring of you, then do that one thing.","k":["meaning","responsibility","questions","purpose"],"src":"After Man's Search for Meaning"},
  {"id":"frankl-03","au":"frankl","s":"Meaning","a":"A strong enough reason will carry me through almost any conditions.","p":"Write your reason down in one sentence and put it where you'll see it on a bad morning.","k":["why","endurance","purpose","resilience"],"src":"After Frankl on having a why to bear almost any how"},
  {"id":"frankl-04","au":"frankl","s":"Meaning","a":"Happiness will not come when chased; it arrives sideways, as a by-product of something worth doing.","p":"Stop optimising for how you feel today and pick something worth finishing instead.","k":["happiness","pursuit","by-product","work"],"src":"After Frankl on happiness ensuing rather than being pursued"},
  {"id":"frankl-05","au":"frankl","s":"Meaning","a":"I find meaning in three places: in work, in love, and in the courage I bring to unavoidable suffering.","p":"Identify which of the three is currently carrying you, and tend to the weakest.","k":["work","love","suffering","logotherapy"],"src":"After the three sources of meaning in logotherapy"},
  {"id":"frankl-06","au":"frankl","s":"Meaning","a":"When a situation cannot be changed, the task becomes changing myself in relation to it.","p":"Name one fixed circumstance and one thing about your posture towards it you could alter.","k":["acceptance","adaptation","change","posture"],"src":"After Frankl on unchangeable circumstances"},
  {"id":"frankl-07","au":"frankl","s":"Meaning","a":"I live as though I am living for the second time, and about to repeat a mistake I can still avoid.","p":"Apply that test to one decision on today's list.","k":["hindsight","decisions","regret","clarity"],"src":"After Frankl's categorical imperative of logotherapy"},
  {"id":"frankl-08","au":"frankl","s":"Meaning","a":"Optimism is not a denial of the facts; it is what I do after I have admitted them.","p":"State the worst honest reading of your situation, then name one action still available.","k":["tragic optimism","realism","hope","action"],"src":"After Frankl on tragic optimism"},
  {"id":"frankl-09","au":"frankl","s":"Meaning","a":"I aim past myself — at a cause or a person — because that is the only way I reliably become more myself.","p":"Do one thing today whose benefit lands entirely on somebody else.","k":["self-transcendence","service","purpose","others"],"src":"After Frankl on self-transcendence"},
  {"id":"frankl-10","au":"frankl","s":"Meaning","a":"Nothing that I have already done or lived can be taken from me; the past is the one safe place to store a life.","p":"Write down one thing you have already done that no future loss can undo.","k":["past","permanence","memory","security"],"src":"After Frankl on the granary of the past"},
  {"id":"thurman-01","au":"thurman","s":"Inner Life","a":"I ask what makes me come alive, then go and do that, because the world needs people who have woken up.","p":"Name the last time you felt fully awake, and schedule more of whatever caused it.","k":["aliveness","vocation","calling","energy"],"src":"After Thurman's counsel on what the world needs"},
  {"id":"thurman-02","au":"thurman","s":"Inner Life","a":"I listen for the sound of the genuine in myself, under all the noise other people have installed.","p":"Sit for five minutes without input and notice what you actually think.","k":["authenticity","silence","self-knowledge","noise"],"src":"After Thurman on the sound of the genuine"},
  {"id":"thurman-03","au":"thurman","s":"Inner Life","a":"I centre down before I act, because a hurried decision is usually somebody else's decision.","p":"Take three slow breaths before answering the next thing that demands an answer.","k":["stillness","centering","pause","discernment"],"src":"After Thurman on centering down"},
  {"id":"thurman-04","au":"thurman","s":"Inner Life","a":"Fear, deception and hatred are the three things that hollow out the powerless; I refuse all three.","p":"Identify which of the three has the strongest grip on you at the moment, and name it out loud.","k":["fear","deception","hate","dignity"],"src":"After Jesus and the Disinherited"},
  {"id":"thurman-05","au":"thurman","s":"Inner Life","a":"My dignity is not issued by anybody else, so it cannot be withdrawn by them either.","p":"Notice one place you've been waiting for permission, and stop waiting.","k":["dignity","permission","worth","independence"],"src":"After Jesus and the Disinherited on inner authority"},
  {"id":"thurman-06","au":"thurman","s":"Inner Life","a":"Hatred takes more from the one who carries it than from the one it is aimed at.","p":"Set down one grievance today — not for their sake, for the weight.","k":["hatred","resentment","release","cost"],"src":"After Thurman on the corrosive work of hate"},
  {"id":"thurman-07","au":"thurman","s":"Inner Life","a":"I look for common ground first, because it is the only ground anything gets built on.","p":"In your next disagreement, state what you agree on before what you don't.","k":["common ground","conflict","dialogue","building"],"src":"After The Search for Common Ground"},
  {"id":"thurman-08","au":"thurman","s":"Inner Life","a":"I keep a place inside that the day cannot reach, and I visit it before the day starts.","p":"Protect the first ten minutes after you wake from anyone else's agenda.","k":["solitude","morning","interior","protection"],"src":"After Thurman on the inner sanctuary"},
  {"id":"thurman-09","au":"thurman","s":"Inner Life","a":"A person's back is only stiffened by being met, not by being flattered.","p":"Tell one person something true and encouraging that they can actually act on.","k":["encouragement","truth","support","strength"],"src":"After Thurman on ministering to the disinherited"},
  {"id":"thurman-10","au":"thurman","s":"Inner Life","a":"I do not have to be sure of the whole road to take the next honest step on it.","p":"Take the next step you can see, and stop demanding a map first.","k":["uncertainty","next step","faith","action"],"src":"After Thurman on walking without the whole map"},
  {"id":"dubois-01","au":"dubois","s":"Education & Identity","a":"I refuse to see myself only through other people's eyes; their measure is not my mirror.","p":"Catch one judgement you've absorbed about yourself and ask who actually wrote it.","k":["double consciousness","self-image","identity","perception"],"src":"After The Souls of Black Folk on double consciousness"},
  {"id":"dubois-02","au":"dubois","s":"Education & Identity","a":"Education is not only training for work; it is the making of a person who can think for themselves.","p":"Read something today that has no career use whatsoever.","k":["education","liberal arts","thinking","utility"],"src":"After Du Bois on education beyond vocational training"},
  {"id":"dubois-03","au":"dubois","s":"Education & Identity","a":"I gather evidence before I argue, because a documented case outlasts a loud one.","p":"Before your next strong claim, find one number or source that supports it.","k":["evidence","scholarship","rigour","argument"],"src":"After The Philadelphia Negro and Du Bois's empirical method"},
  {"id":"dubois-04","au":"dubois","s":"Education & Identity","a":"There is no shame in striving; the shame is in being told the striving is not for me.","p":"Apply for, ask for, or attempt the thing you'd assumed wasn't meant for you.","k":["striving","ambition","aspiration","barriers"],"src":"After The Souls of Black Folk on striving"},
  {"id":"dubois-05","au":"dubois","s":"Education & Identity","a":"The line drawn between people is a problem to be named plainly, not a weather system to be endured.","p":"Name one structural obstacle in your field out loud, accurately, without exaggeration.","k":["colour line","structure","naming","clarity"],"src":"After Du Bois on the problem of the colour line"},
  {"id":"dubois-06","au":"dubois","s":"Education & Identity","a":"I hold two truths at once: the world as it is, and the world I intend to work towards.","p":"Write both versions of one situation and identify the single lever between them.","k":["realism","idealism","tension","strategy"],"src":"After Du Bois on holding critique and hope together"},
  {"id":"dubois-07","au":"dubois","s":"Education & Identity","a":"Culture is inheritance, and I claim mine deliberately rather than receiving it by accident.","p":"Learn one specific thing about where your family came from this month.","k":["heritage","culture","inheritance","roots"],"src":"After Du Bois on cultural inheritance"},
  {"id":"dubois-08","au":"dubois","s":"Education & Identity","a":"Talent unused is not modesty; it is a debt to everyone coming behind me.","p":"Use one capability today that you've been sitting on.","k":["talent","duty","leadership","obligation"],"src":"After Du Bois on the obligations of the educated"},
  {"id":"dubois-09","au":"dubois","s":"Education & Identity","a":"I would rather be uncomfortable and accurate than comfortable and mistaken.","p":"Seek out the strongest version of a view you dislike, and read it properly.","k":["truth","discomfort","accuracy","intellect"],"src":"After Du Bois's insistence on unflattering data"},
  {"id":"dubois-10","au":"dubois","s":"Education & Identity","a":"Progress is not a gift that arrives; it is a thing built by people who kept records.","p":"Document one thing this week that would otherwise go unrecorded.","k":["progress","records","history","evidence"],"src":"After Du Bois's lifelong documentary project"},
  {"id":"baldwin-01","au":"baldwin","s":"Facing Things","a":"Not everything I face can be changed, but nothing changes until I face it.","p":"Name the thing you've been not-looking-at, in writing, today.","k":["facing","denial","change","courage"],"src":"After Baldwin on facing what cannot yet be changed"},
  {"id":"baldwin-02","au":"baldwin","s":"Facing Things","a":"History is not behind me; I carry it, and it shows up in how I react.","p":"Trace one automatic reaction back to where you first learned it.","k":["history","inheritance","reaction","self-knowledge"],"src":"After Baldwin on history being present in us"},
  {"id":"baldwin-03","au":"baldwin","s":"Facing Things","a":"Love is not a soft feeling; it is the state in which growth becomes possible and pretence becomes impossible.","p":"Say one true thing to someone close that you've been softening.","k":["love","honesty","growth","masks"],"src":"After The Fire Next Time on love as a growing up"},
  {"id":"baldwin-04","au":"baldwin","s":"Facing Things","a":"The price of my identity is that I have to actually inhabit it rather than perform it.","p":"Notice one performance you keep up, and drop it for a day.","k":["identity","performance","authenticity","cost"],"src":"After The Price of the Ticket"},
  {"id":"baldwin-05","au":"baldwin","s":"Facing Things","a":"Anger that stays clear is useful; anger that goes blurry only eats the person holding it.","p":"Convert one resentment into a specific, stateable demand or a decision to let go.","k":["anger","clarity","usefulness","resentment"],"src":"After Baldwin on rage and clarity"},
  {"id":"baldwin-06","au":"baldwin","s":"Facing Things","a":"I would rather disturb the peace than keep a peace built on not saying things.","p":"Raise the thing everyone in the room is politely avoiding.","k":["truth-telling","peace","courage","silence"],"src":"After Baldwin on the artist as disturber of the peace"},
  {"id":"baldwin-07","au":"baldwin","s":"Facing Things","a":"People who are hurting other people are usually in trouble themselves; that explains nothing but it clarifies a lot.","p":"Ask what one difficult person is afraid of, before deciding what to do about them.","k":["empathy","conflict","understanding","fear"],"src":"After Baldwin on the interior lives of the cruel"},
  {"id":"baldwin-08","au":"baldwin","s":"Facing Things","a":"I stopped waiting to be accepted on terms set by people who had not examined their own.","p":"Withdraw one request for approval you've been quietly making.","k":["approval","acceptance","terms","independence"],"src":"After Baldwin on refusing others' definitions"},
  {"id":"baldwin-09","au":"baldwin","s":"Facing Things","a":"Innocence that is chosen is not innocence; it is a decision to not know.","p":"Learn the thing about your industry, your city or your family you've preferred not to learn.","k":["innocence","willed ignorance","knowledge","responsibility"],"src":"After Baldwin on the crime of innocence"},
  {"id":"baldwin-10","au":"baldwin","s":"Facing Things","a":"I write and speak to find out what I think, not to announce what I already decided.","p":"Write about the thing you're confused by, before you resolve it.","k":["writing","thinking","discovery","confusion"],"src":"After Baldwin on writing as investigation"},
  {"id":"morrison-01","au":"morrison","s":"Making Things","a":"If the thing I want doesn't exist yet, that is a brief, not a disappointment.","p":"Start the thing you've been waiting for someone else to make.","k":["creation","initiative","absence","making"],"src":"After Morrison on writing the book you want to read"},
  {"id":"morrison-02","au":"morrison","s":"Making Things","a":"The point of getting free is to free somebody else; the point of power is to give it away.","p":"Use one advantage you hold today on behalf of someone who lacks it.","k":["freedom","power","service","liberation"],"src":"After Morrison on the function of freedom"},
  {"id":"morrison-03","au":"morrison","s":"Making Things","a":"I am my own best thing, and I stop outsourcing that verdict.","p":"Write down one quality of yours you value that nobody has ever praised you for.","k":["self-worth","validation","independence","identity"],"src":"After Beloved"},
  {"id":"morrison-04","au":"morrison","s":"Making Things","a":"I refuse to make my work small so that it fits comfortably in somebody else's imagination.","p":"Restore one thing you edited out of your work to make it more palatable.","k":["audience","compromise","authenticity","scale"],"src":"After Morrison on writing without an external gaze"},
  {"id":"morrison-05","au":"morrison","s":"Making Things","a":"Language is not decoration; it is the measure of how carefully we are living.","p":"Say one thing today with real precision instead of the easy approximate phrase.","k":["language","precision","care","expression"],"src":"After Morrison's Nobel lecture on language"},
  {"id":"morrison-06","au":"morrison","s":"Making Things","a":"When someone shows me the whole of their attention, they have given me something; I try to hand it back.","p":"Give one person your undivided attention for the length of a conversation.","k":["attention","presence","generosity","listening"],"src":"After Morrison on truly seeing people"},
  {"id":"morrison-07","au":"morrison","s":"Making Things","a":"Suffering is not automatically instructive; I have to do the work of turning it into something.","p":"Take one hard experience and write what, specifically, it taught you.","k":["suffering","meaning","work","transformation"],"src":"After Morrison on the labour of making meaning"},
  {"id":"morrison-08","au":"morrison","s":"Making Things","a":"Distraction is a tactic; my job is to keep working while it's deployed.","p":"Identify what's currently pulling your attention off your real work, and put it down.","k":["distraction","focus","work","discipline"],"src":"After Morrison on the function of distraction"},
  {"id":"morrison-09","au":"morrison","s":"Making Things","a":"I write about my own world at full detail rather than translating it for outsiders.","p":"Explain something from your life without simplifying it for an imagined stranger.","k":["specificity","translation","voice","detail"],"src":"After Morrison on refusing to explain her world"},
  {"id":"morrison-10","au":"morrison","s":"Making Things","a":"Editing is not the enemy of the work; it is most of the work.","p":"Cut a fifth out of the last thing you wrote and see what improves.","k":["editing","craft","revision","rigour"],"src":"After Morrison's decades as an editor at Random House"},
  {"id":"angelou-01","au":"angelou","s":"Resilience & Grace","a":"People will forget what I said and did, but not how I left them feeling.","p":"Leave one interaction today better than you found it, deliberately.","k":["impact","feeling","kindness","memory"],"src":"After the observation widely attributed to Angelou"},
  {"id":"angelou-02","au":"angelou","s":"Resilience & Grace","a":"I may meet defeats, but I refuse to be defeated — those are different words for a reason.","p":"Separate the setback from the story you've started telling about yourself.","k":["defeat","resilience","distinction","persistence"],"src":"After Angelou on encountering defeats"},
  {"id":"angelou-03","au":"angelou","s":"Resilience & Grace","a":"Courage is the virtue that makes the others possible; without it, kindness collapses under pressure.","p":"Do the small brave thing you've deferred twice already.","k":["courage","virtue","pressure","consistency"],"src":"After Angelou on courage as the greatest virtue"},
  {"id":"angelou-04","au":"angelou","s":"Resilience & Grace","a":"When someone shows me who they are, I believe them the first time.","p":"Stop explaining away one pattern of behaviour you've been excusing.","k":["patterns","trust","clarity","boundaries"],"src":"After Angelou on believing people the first time"},
  {"id":"angelou-05","au":"angelou","s":"Resilience & Grace","a":"I did the best I could with what I knew, and when I knew better I did better — without back-dating the guilt.","p":"Forgive one past decision you made with less information than you have now.","k":["forgiveness","growth","hindsight","guilt"],"src":"After Angelou on knowing better and doing better"},
  {"id":"angelou-06","au":"angelou","s":"Resilience & Grace","a":"I try to be a rainbow in somebody else's cloud, especially on days my own weather is poor.","p":"Encourage one person today when you least feel like it.","k":["encouragement","generosity","weather","others"],"src":"After Angelou on being a rainbow in someone's cloud"},
  {"id":"angelou-07","au":"angelou","s":"Resilience & Grace","a":"Nothing will work unless I do; inspiration is not a delivery service.","p":"Do twenty minutes on the thing you've been waiting to feel ready for.","k":["work","inspiration","effort","readiness"],"src":"After Angelou on nothing working unless you do"},
  {"id":"angelou-08","au":"angelou","s":"Resilience & Grace","a":"There is no greater agony than an untold story carried inside; I would rather tell it badly than carry it.","p":"Tell one person the thing you've never said out loud.","k":["story","silence","expression","release"],"src":"After I Know Why the Caged Bird Sings"},
  {"id":"angelou-09","au":"angelou","s":"Resilience & Grace","a":"Style is what I do with the hand I was actually dealt.","p":"Do one ordinary task today with more care and craft than it strictly requires.","k":["style","craft","circumstance","dignity"],"src":"After Angelou on style and survival"},
  {"id":"angelou-10","au":"angelou","s":"Resilience & Grace","a":"I am human, so nothing human is foreign to me — including the parts I'd rather disown.","p":"Notice one trait you condemn in others and find its smaller version in yourself.","k":["humanity","judgement","self-honesty","empathy"],"src":"After Angelou's use of the Terence maxim"},
  {"id":"drucker-01","au":"drucker","s":"Effectiveness","a":"Doing the right things beats doing things right; efficiency at the wrong task is expensive.","p":"Before optimising anything today, ask whether it should be done at all.","k":["effectiveness","efficiency","priorities","judgement"],"src":"After Drucker on effectiveness versus efficiency"},
  {"id":"drucker-02","au":"drucker","s":"Effectiveness","a":"I record where my time actually goes before I attempt to manage it; memory is an unreliable witness.","p":"Log your time honestly for three days before changing a single thing.","k":["time","measurement","honesty","baseline"],"src":"After The Effective Executive on recording time"},
  {"id":"drucker-03","au":"drucker","s":"Effectiveness","a":"I build on strengths — mine and other people's — because remediating weakness rarely produces excellence.","p":"Assign or claim one task on the basis of who is genuinely best at it.","k":["strengths","weakness","assignment","excellence"],"src":"After Drucker on building on strength"},
  {"id":"drucker-04","au":"drucker","s":"Effectiveness","a":"I write down what I expect to happen, then compare it with what did; that comparison is where learning lives.","p":"Record your expected outcome for one decision, with a date to check it.","k":["feedback analysis","expectations","learning","review"],"src":"After Drucker's feedback analysis method in Managing Oneself"},
  {"id":"drucker-05","au":"drucker","s":"Effectiveness","a":"Asking what I should stop doing is more productive than asking what I should add.","p":"Abandon one activity this week that no longer earns its place.","k":["abandonment","stopping","focus","pruning"],"src":"After Drucker on systematic abandonment"},
  {"id":"drucker-06","au":"drucker","s":"Effectiveness","a":"My question is not what I want to accomplish but what I can contribute here that nobody else will.","p":"Identify your unique contribution to your current project and spend today on that.","k":["contribution","uniqueness","focus","value"],"src":"After The Effective Executive on contribution"},
  {"id":"drucker-07","au":"drucker","s":"Effectiveness","a":"The purpose of the work is out there with the person it serves, not in here with my process.","p":"Talk to one actual user, customer or beneficiary this week.","k":["customer","purpose","outside","service"],"src":"After Drucker on the purpose of a business"},
  {"id":"drucker-08","au":"drucker","s":"Effectiveness","a":"I concentrate on one thing at a time, because doing several things adequately is how nothing gets done well.","p":"Pick the single most important task and finish it before opening anything else.","k":["concentration","single-tasking","focus","completion"],"src":"After The Effective Executive on concentration"},
  {"id":"drucker-09","au":"drucker","s":"Effectiveness","a":"I know how I learn — by reading or by listening — and I stop fighting my own wiring.","p":"Notice whether you absorb things better read or heard, and arrange your inputs accordingly.","k":["learning style","self-knowledge","method","wiring"],"src":"After Managing Oneself"},
  {"id":"drucker-10","au":"drucker","s":"Effectiveness","a":"Every decision needs a name, a deadline and a person; without those it is only a conversation.","p":"Convert one open discussion into a decision with an owner and a date.","k":["decisions","ownership","deadlines","accountability"],"src":"After Drucker on effective decision-making"},
  {"id":"covey-01","au":"covey","s":"Habits & Character","a":"I act on my conditions rather than react to them; between stimulus and response I have room to choose.","p":"Catch one reactive moment today and choose a different response.","k":["proactive","response","choice","initiative"],"src":"After Habit 1: Be Proactive"},
  {"id":"covey-02","au":"covey","s":"Habits & Character","a":"I start with the end in mind, because a ladder against the wrong wall gets you nowhere efficiently.","p":"Write what you want this project to have produced when it's finished.","k":["vision","end in mind","direction","planning"],"src":"After Habit 2: Begin with the End in Mind"},
  {"id":"covey-03","au":"covey","s":"Habits & Character","a":"I put first things first, which mostly means protecting what is important before it becomes urgent.","p":"Schedule one important-but-not-urgent task before the urgent ones arrive.","k":["priorities","urgent","important","quadrant two"],"src":"After Habit 3: Put First Things First"},
  {"id":"covey-04","au":"covey","s":"Habits & Character","a":"I look for the arrangement where both sides genuinely win, and I'm willing to walk if there isn't one.","p":"Reframe one negotiation this week around what would make both parties glad.","k":["win-win","negotiation","mutual","integrity"],"src":"After Habit 4: Think Win-Win"},
  {"id":"covey-05","au":"covey","s":"Habits & Character","a":"I seek to understand before I ask to be understood; diagnosis precedes prescription everywhere else, too.","p":"In your next disagreement, restate their position until they agree you've got it.","k":["listening","understanding","empathy","diagnosis"],"src":"After Habit 5: Seek First to Understand"},
  {"id":"covey-06","au":"covey","s":"Habits & Character","a":"Difference is where the value is; if we both think the same, one of us is redundant.","p":"Deliberately involve someone who sees the problem differently from you.","k":["synergy","difference","collaboration","value"],"src":"After Habit 6: Synergize"},
  {"id":"covey-07","au":"covey","s":"Habits & Character","a":"I sharpen the saw, because working with a blunt one and calling it dedication is just slow.","p":"Take the break, the walk, or the hour of learning you've been skipping.","k":["renewal","rest","maintenance","sharpen the saw"],"src":"After Habit 7: Sharpen the Saw"},
  {"id":"covey-08","au":"covey","s":"Habits & Character","a":"I spend my energy inside my circle of influence, and it quietly grows.","p":"List one worry you can't affect and one you can, then work only on the second.","k":["circle of influence","concern","control","energy"],"src":"After Covey on circles of influence and concern"},
  {"id":"covey-09","au":"covey","s":"Habits & Character","a":"Every small kept promise is a deposit; trust is a balance, not a declaration.","p":"Make one small deposit today — a kept word, a remembered detail, an apology.","k":["trust","emotional bank account","promises","relationships"],"src":"After Covey on the emotional bank account"},
  {"id":"covey-10","au":"covey","s":"Habits & Character","a":"Character comes before technique; personality tricks fail exactly when the pressure is on.","p":"Fix one habit rather than one presentation.","k":["character ethic","personality","integrity","substance"],"src":"After Covey on the character ethic"},
  {"id":"carnegie-01","au":"carnegie","s":"People Skills","a":"I make more friends by being interested than by being interesting.","p":"Ask three real questions before you say anything about yourself today.","k":["interest","curiosity","friendship","listening"],"src":"After How to Win Friends and Influence People"},
  {"id":"carnegie-02","au":"carnegie","s":"People Skills","a":"Criticism almost never produces change; it produces defence.","p":"Replace one piece of criticism today with a specific request.","k":["criticism","defensiveness","change","requests"],"src":"After Carnegie on not criticising, condemning or complaining"},
  {"id":"carnegie-03","au":"carnegie","s":"People Skills","a":"A person's own name is the sweetest sound to them, and remembering it costs me almost nothing.","p":"Learn and use the name of one person you usually pass anonymously.","k":["names","recognition","respect","attention"],"src":"After Carnegie on remembering names"},
  {"id":"carnegie-04","au":"carnegie","s":"People Skills","a":"Nobody ever won an argument; they only won the exchange and lost the person.","p":"Let one small point go today and keep the relationship instead.","k":["arguments","winning","relationships","restraint"],"src":"After Carnegie on the futility of arguments"},
  {"id":"carnegie-05","au":"carnegie","s":"People Skills","a":"When I'm wrong I say so quickly and emphatically, which removes the other person's whole speech.","p":"Admit one error today before anyone has to point it out.","k":["admitting","error","speed","disarming"],"src":"After Carnegie on admitting mistakes quickly"},
  {"id":"carnegie-06","au":"carnegie","s":"People Skills","a":"Appreciation is specific and sincere; flattery is generic and cheap, and everyone can tell.","p":"Praise one exact thing someone did, rather than praising them in general.","k":["appreciation","flattery","specificity","sincerity"],"src":"After Carnegie on honest appreciation"},
  {"id":"carnegie-07","au":"carnegie","s":"People Skills","a":"I let the other person save face; humiliation buys compliance and loses everything else.","p":"Correct someone privately today rather than in front of others.","k":["face","dignity","correction","privacy"],"src":"After Carnegie on letting people save face"},
  {"id":"carnegie-08","au":"carnegie","s":"People Skills","a":"I talk in terms of what they want, because that is the only channel anybody is really listening on.","p":"Rewrite one request from their point of view before you send it.","k":["persuasion","interests","framing","empathy"],"src":"After Carnegie on talking in terms of the other person's interests"},
  {"id":"carnegie-09","au":"carnegie","s":"People Skills","a":"I live in day-tight compartments, because most of what I worry about is not scheduled for today.","p":"Write down tomorrow's worry, close the notebook, and deal with today.","k":["worry","present","compartments","anxiety"],"src":"After How to Stop Worrying and Start Living"},
  {"id":"carnegie-10","au":"carnegie","s":"People Skills","a":"I accept the worst that could happen, then calmly set about improving on it.","p":"Name the actual worst case of your current worry, then list what you'd do next.","k":["worst case","acceptance","calm","planning"],"src":"After Carnegie's formula for dealing with worry"},
  {"id":"hill-01","au":"hill","s":"Purpose & Persistence","a":"A vague ambition is a wish; a definite aim with a date attached is a plan.","p":"Write your main aim in one sentence with a deadline, and read it twice today.","k":["definite purpose","clarity","deadline","aim"],"src":"After Think and Grow Rich on definiteness of purpose"},
  {"id":"hill-02","au":"hill","s":"Purpose & Persistence","a":"Two minds working on the same problem produce a third thing neither had alone.","p":"Bring one stuck problem to a person you trust this week.","k":["mastermind","collaboration","thinking","help"],"src":"After Hill on the mastermind principle"},
  {"id":"hill-03","au":"hill","s":"Purpose & Persistence","a":"Most people quit within sight of the thing; persistence is mostly a refusal to stop three feet early.","p":"Return to one abandoned project and give it one more honest attempt.","k":["persistence","quitting","three feet","endurance"],"src":"After the “three feet from gold” parable in Think and Grow Rich"},
  {"id":"hill-04","au":"hill","s":"Purpose & Persistence","a":"Every setback carries the seed of an equivalent advantage, but I have to go looking for it.","p":"Find the one usable thing inside your most recent failure.","k":["adversity","advantage","seed","reframing"],"src":"After Hill on adversity carrying an equivalent benefit"},
  {"id":"hill-05","au":"hill","s":"Purpose & Persistence","a":"Desire without a plan is just appetite; I write the plan down and revise it when it fails.","p":"Draft the first version of a plan you've been holding only in your head.","k":["planning","desire","revision","organised effort"],"src":"After Think and Grow Rich on organised planning"},
  {"id":"hill-06","au":"hill","s":"Purpose & Persistence","a":"I do more than I am paid for, on the understanding that this is how the rate gets renegotiated.","p":"Deliver one thing this week that exceeds what was actually asked.","k":["extra mile","value","reputation","initiative"],"src":"After Hill on going the extra mile"},
  {"id":"hill-07","au":"hill","s":"Purpose & Persistence","a":"What I repeatedly tell myself becomes what I expect, and what I expect shapes what I attempt.","p":"Catch one habitual self-statement and replace it with an accurate one.","k":["autosuggestion","self-talk","expectation","belief"],"src":"After Think and Grow Rich on autosuggestion"},
  {"id":"hill-08","au":"hill","s":"Purpose & Persistence","a":"Indecision is a decision, and usually the worst one available.","p":"Make one pending decision today, even imperfectly, and move.","k":["decision","indecision","procrastination","action"],"src":"After Hill on the habit of prompt decision"},
  {"id":"hill-09","au":"hill","s":"Purpose & Persistence","a":"Fear of criticism has cost more people more opportunities than any actual critic ever has.","p":"Do the thing you've avoided because of what people might say.","k":["fear","criticism","opportunity","courage"],"src":"After Hill on the six basic fears"},
  {"id":"hill-10","au":"hill","s":"Purpose & Persistence","a":"Controlled attention is the whole game: I decide what gets my mind, or something else will.","p":"Remove one input that has been taking your attention without earning it.","k":["attention","control","focus","inputs"],"src":"After Hill on controlled attention"},
  {"id":"robbins-01","au":"robbins","s":"State & Action","a":"Where my focus goes, my energy follows — so what I choose to look at is not a small decision.","p":"Redirect your attention once today from what's wrong to what's actionable.","k":["focus","energy","attention","direction"],"src":"After Robbins on focus and energy"},
  {"id":"robbins-02","au":"robbins","s":"State & Action","a":"My state changes what I'm capable of, and I can change my state on purpose in about two minutes.","p":"Move your body deliberately before the task you're dreading.","k":["state","physiology","energy","preparation"],"src":"After Robbins on state management"},
  {"id":"robbins-03","au":"robbins","s":"State & Action","a":"The story I tell about a situation is a choice, and a bad story will stop me faster than the facts will.","p":"Write the story you're telling about a current setback, then write a truer one.","k":["story","narrative","belief","reframing"],"src":"After Robbins on state, story and strategy"},
  {"id":"robbins-04","au":"robbins","s":"State & Action","a":"I take massive action rather than measured action, because I can steer once I'm moving.","p":"Do four things towards the goal today instead of researching a fifth option.","k":["action","momentum","volume","execution"],"src":"After Robbins on massive action"},
  {"id":"robbins-05","au":"robbins","s":"State & Action","a":"If someone has already got the result I want, I study their method before inventing my own.","p":"Find one person who has done your goal and reverse-engineer how.","k":["modelling","study","method","shortcut"],"src":"After Robbins on modelling excellence"},
  {"id":"robbins-06","au":"robbins","s":"State & Action","a":"A better question produces a better answer; “why me” and “what now” lead to different lives.","p":"Replace one complaint with a question that has an answer.","k":["questions","framing","problem-solving","language"],"src":"After Robbins on the quality of your questions"},
  {"id":"robbins-07","au":"robbins","s":"State & Action","a":"It is in my moments of decision that my direction is set, not in my moments of intention.","p":"Turn one intention into a decision with a first action today.","k":["decision","destiny","intention","commitment"],"src":"After Robbins on decisions shaping destiny"},
  {"id":"robbins-08","au":"robbins","s":"State & Action","a":"Progress equals happiness more reliably than arrival does; I set things up so I can feel the movement.","p":"Track one visible measure of progress on your main project this week.","k":["progress","happiness","measurement","momentum"],"src":"After Robbins on progress equalling happiness"},
  {"id":"robbins-09","au":"robbins","s":"State & Action","a":"Once my own needs are met, contribution is the only thing that keeps the meaning topped up.","p":"Contribute something with no transactional return this week.","k":["contribution","meaning","six human needs","giving"],"src":"After the six human needs, contribution and growth"},
  {"id":"robbins-10","au":"robbins","s":"State & Action","a":"Complexity is where good intentions go to die; I want the simplest version that works.","p":"Cut your current plan down to the three steps that actually matter.","k":["simplicity","complexity","plans","execution"],"src":"After Robbins on simplicity in execution"},
  {"id":"tyson-01","au":"tyson","s":"Evidence & Perspective","a":"What is true stays true without my agreement, so I hold my beliefs loosely enough that evidence can move them.","p":"Name one belief you hold and state what evidence would change it. If nothing would, it isn't a belief — it's an attachment.","k":["evidence","belief","truth","falsifiability"],"src":"After Tyson on science being true whether or not you believe in it"},
  {"id":"tyson-02","au":"tyson","s":"Evidence & Perspective","a":"“I don't know” is a complete and respectable sentence, and pretending otherwise is how errors get expensive.","p":"Say it once today where you'd normally improvise an answer, then go and find out.","k":["ignorance","humility","honesty","admitting"],"src":"After Tyson on the value of admitting ignorance"},
  {"id":"tyson-03","au":"tyson","s":"Evidence & Perspective","a":"The universe is under no obligation to make sense to me; my confusion is information about me, not about it.","p":"Take one thing that seems obviously wrong and check whether you've understood it before you dismiss it.","k":["confusion","reality","intuition","humility"],"src":"After Tyson on the universe's lack of obligation"},
  {"id":"tyson-04","au":"tyson","s":"Evidence & Perspective","a":"I keep three piles separate: what I know, what I don't know, and what I cannot know — and I notice when I'm mixing them.","p":"Sort your current problem into those three piles and act only on the first.","k":["knowledge","uncertainty","limits","clarity"],"src":"After Tyson on the boundaries of knowledge"},
  {"id":"tyson-05","au":"tyson","s":"Evidence & Perspective","a":"An objective truth, a personal truth and a political truth are three different animals, and most arguments are people mistaking one for another.","p":"In your next disagreement, work out which of the three you're each actually defending.","k":["objective truth","personal truth","argument","categories"],"src":"After Starry Messenger"},
  {"id":"tyson-06","au":"tyson","s":"Evidence & Perspective","a":"Seen from far enough away, most of what I'm defending is a line somebody drew, and I can choose how hard to defend it.","p":"Take one conflict you're in and describe it as it would look from orbit.","k":["cosmic perspective","conflict","scale","tribalism"],"src":"After the cosmic perspective in Starry Messenger"},
  {"id":"tyson-07","au":"tyson","s":"Evidence & Perspective","a":"I'm bad at probability by default, so I do the arithmetic instead of trusting the feeling.","p":"Before your next risk judgement, write down the actual numbers rather than how alarming it seems.","k":["probability","innumeracy","risk","arithmetic"],"src":"After Tyson on innumeracy and misjudged risk"},
  {"id":"tyson-08","au":"tyson","s":"Evidence & Perspective","a":"Children are born curious and get trained out of it; I try to be untrained.","p":"Ask one question today that you'd normally think was too basic to ask out loud.","k":["curiosity","questions","children","learning"],"src":"After Tyson on children as natural scientists"},
  {"id":"tyson-09","au":"tyson","s":"Evidence & Perspective","a":"Being taught what to think produces someone who can be told anything; I'd rather learn how to think.","p":"Take one claim you accepted this week and trace it back to where it actually came from.","k":["critical thinking","education","method","sources"],"src":"After Tyson on scientific literacy as a way of thinking"},
  {"id":"tyson-10","au":"tyson","s":"Evidence & Perspective","a":"I'm not small in the universe — I'm made of it, and that is a better fact than the one that makes people feel tiny.","p":"When the scale of things feels crushing today, try the other reading of the same fact.","k":["belonging","cosmos","scale","perspective"],"src":"After Tyson on being part of the universe rather than dwarfed by it"},
  {"id":"kahneman-01","au":"kahneman","s":"Judgement & Bias","a":"I have a fast mind that answers instantly and a slow one that checks; the trouble is the fast one never says it's unsure.","p":"Notice one snap judgement today and deliberately hand it to the slower process.","k":["system 1","system 2","intuition","checking"],"src":"After Thinking, Fast and Slow"},
  {"id":"kahneman-02","au":"kahneman","s":"Judgement & Bias","a":"What I can see is not all there is, but my confidence is built only from what I can see.","p":"Before deciding, ask what information would exist if you were wrong — and whether you'd have it.","k":["WYSIATI","evidence","confidence","blind spots"],"src":"After Kahneman on “what you see is all there is”"},
  {"id":"kahneman-03","au":"kahneman","s":"Judgement & Bias","a":"The first number I hear drags every number after it, whether or not it deserves to.","p":"In your next negotiation or estimate, write your figure down before you hear theirs.","k":["anchoring","estimates","negotiation","numbers"],"src":"After Kahneman and Tversky on anchoring"},
  {"id":"kahneman-04","au":"kahneman","s":"Judgement & Bias","a":"Losing stings about twice as much as gaining pleases, which explains most of my worst caution.","p":"Reframe one avoided decision in terms of what standing still is costing you.","k":["loss aversion","risk","caution","framing"],"src":"After prospect theory"},
  {"id":"kahneman-05","au":"kahneman","s":"Judgement & Bias","a":"My plans assume everything goes well, because I built them from the best-case story I could imagine.","p":"Add the time you've never once managed to save, then plan a pre-mortem: assume it failed, and say why.","k":["planning fallacy","optimism","pre-mortem","estimates"],"src":"After Kahneman on the planning fallacy"},
  {"id":"kahneman-06","au":"kahneman","s":"Judgement & Bias","a":"An extreme result is usually followed by an ordinary one, and I keep crediting my interventions for the arithmetic.","p":"Before concluding something worked, ask what would have happened anyway.","k":["regression to the mean","causation","evaluation","luck"],"src":"After Kahneman on regression to the mean"},
  {"id":"kahneman-07","au":"kahneman","s":"Judgement & Bias","a":"How easily an example comes to mind is not how often it happens.","p":"When something feels risky, check the base rate before you check your gut.","k":["availability","base rates","risk","frequency"],"src":"After the availability heuristic"},
  {"id":"kahneman-08","au":"kahneman","s":"Judgement & Bias","a":"The self who lives an experience and the self who remembers it want different things, and only one of them chooses.","p":"Ask whether you're building a good memory or a good day — and whether that's the one you meant to build.","k":["experiencing self","remembering self","memory","choice"],"src":"After Kahneman on the two selves"},
  {"id":"dweck-01","au":"dweck","s":"Mindset & Learning","a":"Ability is not a fixed quantity I was issued; it is something that responds to what I do with it.","p":"Take one thing you've decided you're “not good at” and give it four deliberate sessions.","k":["growth mindset","fixed mindset","ability","malleability"],"src":"After Mindset"},
  {"id":"dweck-02","au":"dweck","s":"Mindset & Learning","a":"I am not bad at this; I am not good at it yet, and the word doing the work is “yet”.","p":"Add “yet” to the end of one thing you've said about yourself this week.","k":["yet","language","progress","self-talk"],"src":"After Dweck on the power of yet"},
  {"id":"dweck-03","au":"dweck","s":"Mindset & Learning","a":"Praise aimed at how clever someone is makes them cautious; praise aimed at what they did makes them brave.","p":"Compliment one person today on their method rather than their talent.","k":["praise","process","effort","encouragement"],"src":"After Dweck's research on praise and risk-taking"},
  {"id":"dweck-04","au":"dweck","s":"Mindset & Learning","a":"Difficulty is information about where the learning is, not a verdict about who I am.","p":"When something feels hard today, name what specifically is hard rather than concluding anything about yourself.","k":["difficulty","information","learning","self-concept"],"src":"After Mindset on the meaning of struggle"},
  {"id":"dweck-05","au":"dweck","s":"Mindset & Learning","a":"Effort alone isn't the point; effort plus a change of strategy is.","p":"If something hasn't worked after three honest tries, change the approach rather than the intensity.","k":["strategy","effort","false growth mindset","adaptation"],"src":"After Dweck's later corrections on “false growth mindset”"},
  {"id":"dweck-06","au":"dweck","s":"Mindset & Learning","a":"I watch how I react to other people's success, because envy usually means I've decided ability is a fixed pie.","p":"Ask one person who's better than you how they got there.","k":["envy","comparison","success","curiosity"],"src":"After Mindset on responses to others' achievement"},
  {"id":"dweck-07","au":"dweck","s":"Mindset & Learning","a":"Nobody holds one mindset all the time; I have domains where I'm brave and domains where I'm brittle.","p":"Name the area where you're most defensive about criticism — that's the fixed one.","k":["domains","self-awareness","defensiveness","nuance"],"src":"After Dweck on mindsets varying by domain"},
  {"id":"dweck-08","au":"dweck","s":"Mindset & Learning","a":"Feedback that stings is usually feedback that's landed; I try to hear it before I decide how to feel about it.","p":"Receive one piece of criticism today without explaining yourself first.","k":["feedback","criticism","listening","defensiveness"],"src":"After Mindset on responses to feedback"},
  {"id":"brown-01","au":"brown","s":"Courage & Connection","a":"Vulnerability is not weakness; it is the most accurate measure of courage I have available.","p":"Do one thing today where the outcome isn't guaranteed and you can't control what people think.","k":["vulnerability","courage","risk","exposure"],"src":"After Daring Greatly"},
  {"id":"brown-02","au":"brown","s":"Courage & Connection","a":"Guilt says I did something bad; shame says I am something bad — and only one of those can be worked with.","p":"Restate one thing you feel bad about as a behaviour rather than an identity.","k":["shame","guilt","identity","behaviour"],"src":"After Brown's distinction between shame and guilt"},
  {"id":"brown-03","au":"brown","s":"Courage & Connection","a":"Clear is kind; unclear is unkind, however gently the vagueness is delivered.","p":"Say the direct version of the thing you were going to hint at.","k":["clarity","kindness","directness","communication"],"src":"After Dare to Lead"},
  {"id":"brown-04","au":"brown","s":"Courage & Connection","a":"I take criticism seriously from people who are also in the arena, and not from those in the cheap seats.","p":"Write down whose feedback actually counts for you, and stop consulting the rest.","k":["arena","criticism","audience","selectivity"],"src":"After Daring Greatly and the Roosevelt “man in the arena” passage"},
  {"id":"brown-05","au":"brown","s":"Courage & Connection","a":"Belonging asks me to be myself; fitting in asks me to be acceptable, and they are opposite requirements.","p":"Notice one place you're editing yourself to fit, and stop for a day.","k":["belonging","fitting in","authenticity","conformity"],"src":"After Braving the Wilderness"},
  {"id":"brown-06","au":"brown","s":"Courage & Connection","a":"The armour that protects me from being hurt also stops anything reaching me.","p":"Drop one habitual defence — the joke, the pre-emptive apology, the deflection — in one conversation.","k":["armour","defences","protection","openness"],"src":"After Daring Greatly on armoured living"},
  {"id":"brown-07","au":"brown","s":"Courage & Connection","a":"I would rather be uncomfortable and honest than comfortable and quietly resentful.","p":"Raise the small thing now rather than letting it become the big thing later.","k":["discomfort","honesty","resentment","timing"],"src":"After Dare to Lead on choosing courage over comfort"},
  {"id":"brown-08","au":"brown","s":"Courage & Connection","a":"Boundaries are not the opposite of generosity; they are what makes sustained generosity possible.","p":"Say what you can actually do, rather than agreeing and resenting it.","k":["boundaries","generosity","capacity","resentment"],"src":"After Brown's research on boundaries and compassion"},
  {"id":"clear-01","au":"clear","s":"Habits & Systems","a":"I don't rise to my goals; I fall to my systems, so I build the system and let the goal look after itself.","p":"Replace one goal on your list with the daily process that would achieve it.","k":["systems","goals","process","design"],"src":"After Atomic Habits"},
  {"id":"clear-02","au":"clear","s":"Habits & Systems","a":"One per cent better is invisible today and decisive in a year; the maths is doing work my feelings can't see.","p":"Make one improvement so small it feels pointless, and do it again tomorrow.","k":["marginal gains","compounding","small","patience"],"src":"After Atomic Habits on aggregation of marginal gains"},
  {"id":"clear-03","au":"clear","s":"Habits & Systems","a":"Every action is a vote for the kind of person I'm becoming, and identity is what the tally adds up to.","p":"Ask what someone who already is that person would do in the next hour, then do it.","k":["identity","votes","becoming","behaviour"],"src":"After Atomic Habits on identity-based habits"},
  {"id":"clear-04","au":"clear","s":"Habits & Systems","a":"I make the good thing obvious and the bad thing awkward, because willpower loses to friction every time.","p":"Move one object today to make a habit easier or harder to start.","k":["environment","friction","cues","design"],"src":"After the four laws of behaviour change"},
  {"id":"clear-05","au":"clear","s":"Habits & Systems","a":"When I don't want to do it, I do the two-minute version, because showing up is the habit and the rest is detail.","p":"Shrink the task you're avoiding to two minutes and start it.","k":["two-minute rule","starting","showing up","momentum"],"src":"After Atomic Habits on the two-minute rule"},
  {"id":"clear-06","au":"clear","s":"Habits & Systems","a":"Missing once is an accident; missing twice is the start of a new habit, so I never miss twice.","p":"If you skipped yesterday, do the smallest possible version today rather than restarting Monday.","k":["consistency","recovery","streaks","forgiveness"],"src":"After Atomic Habits on never missing twice"},
  {"id":"clear-07","au":"clear","s":"Habits & Systems","a":"Results lag behind effort long enough to make quitting feel rational; the valley is part of the shape, not a signal.","p":"Name where you are on the curve before you decide anything has failed.","k":["plateau","latent potential","lag","persistence"],"src":"After Atomic Habits on the plateau of latent potential"},
  {"id":"clear-08","au":"clear","s":"Habits & Systems","a":"I attach the new habit to one I already do without thinking, because an existing routine is free scaffolding.","p":"Complete this sentence and use it today: after I [existing habit], I will [new habit].","k":["habit stacking","routine","anchoring","scaffolding"],"src":"After Atomic Habits on habit stacking"},
  {"id":"newport-01","au":"newport","s":"Attention & Craft","a":"Concentrating without distraction on something hard is now rare, which is precisely why it's valuable.","p":"Block ninety uninterrupted minutes for the hardest thing on your list.","k":["deep work","concentration","scarcity","value"],"src":"After Deep Work"},
  {"id":"newport-02","au":"newport","s":"Attention & Craft","a":"Every glance at something else leaves residue; my attention doesn't move cleanly between tasks.","p":"Close everything not related to the current task before you begin it.","k":["attention residue","switching","focus","single-tasking"],"src":"After Newport on attention residue"},
  {"id":"newport-03","au":"newport","s":"Attention & Craft","a":"“Follow your passion” is bad advice; become genuinely good at something and the passion tends to follow the competence.","p":"Pick the skill in your work that's most rare and valuable, and practise it deliberately this week.","k":["craftsman mindset","passion","skill","competence"],"src":"After So Good They Can't Ignore You"},
  {"id":"newport-04","au":"newport","s":"Attention & Craft","a":"Busyness is what work looks like when there's no measure of whether it produced anything.","p":"At day's end, write what you made rather than what you attended.","k":["busyness","productivity","output","measurement"],"src":"After Newport on busyness as proxy for productivity"},
  {"id":"newport-05","au":"newport","s":"Attention & Craft","a":"I schedule what I'll do rather than reacting to what arrives; an unplanned day belongs to whoever emails first.","p":"Assign every hour of tomorrow a job in advance, and adjust rather than abandon.","k":["time blocking","planning","reactivity","control"],"src":"After Deep Work on time-blocking"},
  {"id":"newport-06","au":"newport","s":"Attention & Craft","a":"If I can never tolerate boredom, I've trained myself out of the state deep thinking requires.","p":"Wait somewhere today without reaching for your phone.","k":["boredom","stimulation","training","attention"],"src":"After Deep Work on embracing boredom"},
  {"id":"newport-07","au":"newport","s":"Attention & Craft","a":"A tool earns its place by whether it substantially serves something I value, not by whether it offers some benefit.","p":"Audit one app against that test and remove it if it only clears the low bar.","k":["digital minimalism","tools","audit","value"],"src":"After Digital Minimalism"},
  {"id":"newport-08","au":"newport","s":"Attention & Craft","a":"I decide when work stops, because a day with no edge expands to fill everything and sharpens nothing.","p":"Set a shutdown time tonight and honour it, including the checking.","k":["shutdown","boundaries","rest","recovery"],"src":"After Deep Work on the shutdown ritual"},
  {"id":"taleb-01","au":"taleb","s":"Risk & Uncertainty","a":"Some things break under stress, some resist it, and some improve because of it — I want to be the third.","p":"Find one area where a setback would strengthen you, and one where it would ruin you. Reduce the second.","k":["antifragile","robust","fragile","stress"],"src":"After Antifragile"},
  {"id":"taleb-02","au":"taleb","s":"Risk & Uncertainty","a":"The events that decide my life are the ones I didn't have in the model.","p":"Ask what would have to happen for your plan to fail completely, then check whether you'd survive it.","k":["black swan","tail risk","models","surprise"],"src":"After The Black Swan"},
  {"id":"taleb-03","au":"taleb","s":"Risk & Uncertainty","a":"I weight advice by what the adviser loses if they're wrong.","p":"Before taking a recommendation, ask what it costs that person if it goes badly.","k":["skin in the game","incentives","advice","accountability"],"src":"After Skin in the Game"},
  {"id":"taleb-04","au":"taleb","s":"Risk & Uncertainty","a":"Removing the harmful is more reliable than adding the beneficial, and far easier to be sure about.","p":"Subtract one thing this week rather than adding an improvement.","k":["via negativa","subtraction","removal","reliability"],"src":"After Taleb on via negativa"},
  {"id":"taleb-05","au":"taleb","s":"Risk & Uncertainty","a":"What has survived a long time will probably survive longer; age is evidence in the things that aren't perishable.","p":"When choosing a book, a method or a tool, prefer the one that's already lasted decades.","k":["Lindy effect","time","durability","survival"],"src":"After Taleb on the Lindy effect"},
  {"id":"taleb-06","au":"taleb","s":"Risk & Uncertainty","a":"I go very safe with most of it and genuinely reckless with a small slice, rather than moderately risky with all of it.","p":"Split one commitment into a protected core and a small deliberate bet.","k":["barbell","risk","allocation","asymmetry"],"src":"After the barbell strategy in Antifragile"},
  {"id":"taleb-07","au":"taleb","s":"Risk & Uncertainty","a":"I invent a story to explain what happened, then mistake the story for the mechanism.","p":"Take one confident explanation you hold and ask what evidence separates it from the alternatives.","k":["narrative fallacy","explanation","hindsight","causation"],"src":"After The Black Swan on the narrative fallacy"},
  {"id":"taleb-08","au":"taleb","s":"Risk & Uncertainty","a":"I collect options — things with small costs and open-ended payoffs — and I don't need to predict which one pays.","p":"Do one cheap thing this week whose upside you cannot currently calculate.","k":["optionality","asymmetry","upside","exposure"],"src":"After Antifragile on optionality"},
  {"id":"grant-01","au":"grant","s":"Rethinking","a":"I hold confident humility: sure of my ability to work it out, unsure that I currently have.","p":"State one view you hold and the confidence level you'd actually bet at.","k":["confident humility","certainty","calibration","doubt"],"src":"After Think Again"},
  {"id":"grant-02","au":"grant","s":"Rethinking","a":"I keep slipping into preacher, prosecutor or politician when the useful mode is scientist.","p":"Notice which of the four you're in during your next disagreement, and switch.","k":["scientist mode","preacher","prosecutor","politician"],"src":"After Think Again on modes of thinking"},
  {"id":"grant-03","au":"grant","s":"Rethinking","a":"Being wrong is not a defeat if I detach my opinions from my identity.","p":"Say “I've changed my mind” out loud about one thing this month.","k":["identity","opinions","changing mind","detachment"],"src":"After Think Again on detaching identity from opinion"},
  {"id":"grant-04","au":"grant","s":"Rethinking","a":"I want a challenge network more than a support network — people who'll tell me the thing rather than reassure me.","p":"Ask the most rigorous person you know to poke holes in your current plan.","k":["challenge network","feedback","rigour","support"],"src":"After Think Again on challenge networks"},
  {"id":"grant-05","au":"grant","s":"Rethinking","a":"Disagreement about the task is productive; disagreement about the person is corrosive, and people confuse the two constantly.","p":"Argue the idea hard and the person not at all, and say so explicitly.","k":["task conflict","relationship conflict","debate","respect"],"src":"After Grant's work on conflict types"},
  {"id":"grant-06","au":"grant","s":"Rethinking","a":"Givers finish both last and first; the difference is whether they set any limits at all.","p":"Give generously this week to one specific person, and decline one request that would cost you the capacity.","k":["givers","takers","generosity","limits"],"src":"After Give and Take"},
  {"id":"grant-07","au":"grant","s":"Rethinking","a":"The most useful person in the room is often the disagreeable one who actually wants me to succeed.","p":"Thank someone who has given you unwelcome and accurate feedback.","k":["disagreeable givers","criticism","allies","honesty"],"src":"After Grant on disagreeable givers"},
  {"id":"grant-08","au":"grant","s":"Rethinking","a":"Originality is mostly volume plus editing; the people with the best ideas also had the most bad ones.","p":"Generate twenty options before choosing, rather than defending your first.","k":["originality","volume","ideas","editing"],"src":"After Originals"},
  {"id":"burkeman-01","au":"burkeman","s":"Finitude","a":"I get about four thousand weeks, and no productivity system is going to change that number.","p":"Decide one thing you are going to deliberately not do this year, and stop feeling guilty about it.","k":["finitude","time","limits","acceptance"],"src":"After Four Thousand Weeks"},
  {"id":"burkeman-02","au":"burkeman","s":"Finitude","a":"Getting faster at everything just makes more arrive; efficiency is a treadmill, not an exit.","p":"Resist clearing the inbox today and do the one thing that mattered instead.","k":["efficiency trap","email","throughput","futility"],"src":"After Burkeman on the efficiency trap"},
  {"id":"burkeman-03","au":"burkeman","s":"Finitude","a":"Choosing anything means losing everything else, and the loss is the price of the choice being real.","p":"Commit to one option and let the alternatives go rather than keeping them warm.","k":["choice","loss","commitment","alternatives"],"src":"After Four Thousand Weeks on the cost of choosing"},
  {"id":"burkeman-04","au":"burkeman","s":"Finitude","a":"I will fail at something; the only question is whether I chose which thing.","p":"Name what you are consciously going to be mediocre at, so the rest can be good.","k":["strategic underachievement","failure","choice","priorities"],"src":"After Burkeman on choosing what to fail at"},
  {"id":"burkeman-05","au":"burkeman","s":"Finitude","a":"Nothing I do is cosmically required of me, and that is a relief rather than a demotion.","p":"Take one task you've been treating as existential and rate its actual stakes honestly.","k":["cosmic insignificance","pressure","relief","proportion"],"src":"After Four Thousand Weeks on cosmic insignificance therapy"},
  {"id":"burkeman-06","au":"burkeman","s":"Finitude","a":"Waiting to feel ready is a way of never starting, because readiness arrives after beginning, not before.","p":"Begin the thing today at the level of preparedness you currently have.","k":["readiness","starting","procrastination","preparation"],"src":"After Burkeman on the impossibility of feeling ready"},
  {"id":"burkeman-07","au":"burkeman","s":"Finitude","a":"Patience is a skill I can practise: staying with something slow without reaching for the next stimulation.","p":"Do one slow thing today at its own speed without checking anything.","k":["patience","slowness","attention","practice"],"src":"After Four Thousand Weeks on patience as a superpower"},
  {"id":"burkeman-08","au":"burkeman","s":"Finitude","a":"I stop treating today as preparation for a real life that starts later; this is the life.","p":"Do one thing today purely because it's worth doing now, not because it builds towards something.","k":["present","instrumentalising","meaning","now"],"src":"After Four Thousand Weeks on using the present as a means"},
  {"id":"stevenson-01","au":"stevenson","s":"Justice & Mercy","a":"Each of us is more than the worst thing we have ever done.","p":"Withhold one final verdict you've passed on someone — including on yourself.","k":["mercy","judgement","worth","redemption"],"src":"After Just Mercy"},
  {"id":"stevenson-02","au":"stevenson","s":"Justice & Mercy","a":"I get proximate to the problem, because you cannot understand something you've only read about.","p":"Go where the thing you care about actually happens, once, this month.","k":["proximity","understanding","presence","engagement"],"src":"After Stevenson on getting proximate"},
  {"id":"stevenson-03","au":"stevenson","s":"Justice & Mercy","a":"The narrative is upstream of the policy; change what people believe and the rules follow.","p":"Identify the story behind a rule you disagree with, and argue with the story.","k":["narrative","policy","belief","upstream"],"src":"After Stevenson on changing narratives"},
  {"id":"stevenson-04","au":"stevenson","s":"Justice & Mercy","a":"Hope is not a feeling that arrives; it is a stance I take before the evidence is in.","p":"Act once today on a hope you cannot currently justify.","k":["hope","stance","evidence","commitment"],"src":"After Just Mercy on hope as orientation"},
  {"id":"stevenson-05","au":"stevenson","s":"Justice & Mercy","a":"Doing anything worthwhile requires being willing to be uncomfortable, and I stop treating discomfort as a stop signal.","p":"Stay in one uncomfortable conversation past the point you'd normally exit.","k":["discomfort","commitment","difficulty","persistence"],"src":"After Stevenson on the necessity of discomfort"},
  {"id":"stevenson-06","au":"stevenson","s":"Justice & Mercy","a":"The opposite of poverty is not wealth; it is justice.","p":"Ask, of one problem you'd solve with money, what would fix it structurally instead.","k":["poverty","justice","structure","framing"],"src":"After Just Mercy"},
  {"id":"stevenson-07","au":"stevenson","s":"Justice & Mercy","a":"Mercy is most itself when it is undeserved; that is not a loophole in justice but the point of it.","p":"Extend one piece of grace this week to someone with no claim on it.","k":["mercy","grace","undeserved","forgiveness"],"src":"After Just Mercy on the nature of mercy"},
  {"id":"stevenson-08","au":"stevenson","s":"Justice & Mercy","a":"I don't get to skip the history; a wound left undescribed doesn't heal, it just stops being mentioned.","p":"Learn one uncomfortable fact about the history of a place or institution you're part of.","k":["history","truth","reckoning","silence"],"src":"After Stevenson on truth and reconciliation"},
  {"id":"wilkerson-01","au":"wilkerson","s":"Structure & Story","a":"Caste is the bones and race is the skin; if I only argue about the skin I never touch the structure.","p":"Ask of one unfairness you've noticed: what is the ranking underneath it?","k":["caste","structure","race","hierarchy"],"src":"After Caste: The Origins of Our Discontents"},
  {"id":"wilkerson-02","au":"wilkerson","s":"Structure & Story","a":"I inherited the house, not the cracks; I'm not to blame for them and I am responsible for the repairs.","p":"Take responsibility for one inherited problem you didn't create.","k":["inheritance","responsibility","blame","repair"],"src":"After Wilkerson's old-house metaphor in Caste"},
  {"id":"wilkerson-03","au":"wilkerson","s":"Structure & Story","a":"Radical empathy is not imagining how I'd feel in their place; it is learning how they feel in theirs.","p":"Ask someone what an experience was actually like, and resist substituting your own version.","k":["radical empathy","listening","projection","understanding"],"src":"After Caste on radical empathy"},
  {"id":"wilkerson-04","au":"wilkerson","s":"Structure & Story","a":"Leaving is an act, not a failure; people who move are exercising the only power available to them.","p":"Consider whether the thing you're enduring is something you're permitted to simply leave.","k":["migration","agency","leaving","power"],"src":"After The Warmth of Other Suns"},
  {"id":"wilkerson-05","au":"wilkerson","s":"Structure & Story","a":"A statistic is a story with the person removed; I try to keep the person in.","p":"Attach one specific human account to a number you're about to use.","k":["statistics","narrative","specificity","humanity"],"src":"After Wilkerson's method of narrative history"},
  {"id":"wilkerson-06","au":"wilkerson","s":"Structure & Story","a":"The system runs whether or not anyone in it intends anything; blaming individuals lets the machinery keep working.","p":"Look for the process rather than the villain in one situation that frustrates you.","k":["systems","intention","blame","machinery"],"src":"After Caste on systems operating without individual malice"},
  {"id":"wilkerson-07","au":"wilkerson","s":"Structure & Story","a":"Everyone in a hierarchy pays something for it, including those it appears to serve.","p":"Ask what a structure you benefit from also costs you.","k":["hierarchy","cost","complicity","benefit"],"src":"After Caste on the costs to all participants"},
  {"id":"wilkerson-08","au":"wilkerson","s":"Structure & Story","a":"Ordinary people made ordinary choices, and that is how the large thing was built and how it gets unbuilt.","p":"Make one small choice today that a different system would require.","k":["ordinary choices","aggregation","change","agency"],"src":"After Wilkerson on the accumulation of individual decisions"},
  {"id":"coates-01","au":"coates","s":"Writing & Reckoning","a":"Writing is failing repeatedly in public view until something works; the struggle is the method, not a sign it's going badly.","p":"Write a bad draft today rather than waiting for a good one.","k":["writing","failure","drafts","method"],"src":"After Coates on writing as struggle"},
  {"id":"coates-02","au":"coates","s":"Writing & Reckoning","a":"I want the specific fact rather than the general feeling; vagueness is where comfortable lies live.","p":"Replace one sweeping claim you've made with the particular evidence behind it.","k":["specificity","evidence","vagueness","precision"],"src":"After Coates on the discipline of specificity"},
  {"id":"coates-03","au":"coates","s":"Writing & Reckoning","a":"I refuse the easy hope that lets me stop looking; honest despair is more useful than convenient optimism.","p":"Sit with one problem today without rushing to the silver lining.","k":["hope","despair","honesty","comfort"],"src":"After Between the World and Me"},
  {"id":"coates-04","au":"coates","s":"Writing & Reckoning","a":"Reading widely is an apprenticeship, and I serve it rather than expecting to arrive fully formed.","p":"Read something today by someone who would disagree with you about method, not just conclusions.","k":["reading","apprenticeship","learning","range"],"src":"After Coates on his self-education"},
  {"id":"coates-05","au":"coates","s":"Writing & Reckoning","a":"History is not a backdrop; it is a set of decisions that are still paying out.","p":"Trace one current condition back to a specific past decision rather than to “how things are”.","k":["history","decisions","consequences","causation"],"src":"After The Case for Reparations"},
  {"id":"coates-06","au":"coates","s":"Writing & Reckoning","a":"Curiosity outlasts anger; anger got me to the question and curiosity is what answers it.","p":"Turn one thing you're angry about into a question you don't know the answer to.","k":["curiosity","anger","questions","inquiry"],"src":"After Coates on curiosity as an engine"},
  {"id":"coates-07","au":"coates","s":"Writing & Reckoning","a":"I don't need to be a spokesperson for anyone; I only need to be accurate about what I actually see.","p":"Say the thing you actually think rather than the thing your group is expected to think.","k":["voice","representation","accuracy","independence"],"src":"After Coates on writing from the individual"},
  {"id":"coates-08","au":"coates","s":"Writing & Reckoning","a":"Beauty is not a distraction from difficulty; it's often the only thing that makes difficulty survivable.","p":"Give attention to one beautiful thing today without justifying it.","k":["beauty","struggle","survival","attention"],"src":"After The Beautiful Struggle"},
  {"id":"adichie-01","au":"adichie","s":"Story & Voice","a":"A single story about a person or a place isn't wrong so much as incomplete, and incompleteness does most of the damage.","p":"Find a second story about a group you hold one story about.","k":["single story","stereotype","incompleteness","perspective"],"src":"After The Danger of a Single Story"},
  {"id":"adichie-02","au":"adichie","s":"Story & Voice","a":"Who tells the story, and when they start it, decides almost everything about what it means.","p":"Ask where a narrative you've accepted chose to begin, and what starting earlier would change.","k":["narrative","framing","power","beginnings"],"src":"After The Danger of a Single Story"},
  {"id":"adichie-03","au":"adichie","s":"Story & Voice","a":"I write the world I actually know rather than the one I've been shown in books.","p":"Describe something from your own life in its own terms, without borrowing someone else's frame.","k":["authenticity","voice","specificity","representation"],"src":"After Adichie on discovering African literature as a child"},
  {"id":"adichie-04","au":"adichie","s":"Story & Voice","a":"Culture does not make people; people make culture, and so it can be remade.","p":"Question one custom you follow because it's the custom.","k":["culture","change","tradition","agency"],"src":"After We Should All Be Feminists"},
  {"id":"adichie-05","au":"adichie","s":"Story & Voice","a":"Teaching a person to shrink so that others feel large costs everybody the person they'd have become.","p":"Take up the appropriate amount of space in one situation where you'd usually shrink.","k":["shrinking","ambition","self","space"],"src":"After We Should All Be Feminists"},
  {"id":"adichie-06","au":"adichie","s":"Story & Voice","a":"Language carries assumptions I didn't choose; I can notice them without abandoning the language.","p":"Catch one phrase you use that assumes something you don't believe.","k":["language","assumptions","awareness","words"],"src":"After Adichie on language and inherited assumption"},
  {"id":"adichie-07","au":"adichie","s":"Story & Voice","a":"Literature is practice at being someone else, which is the only way I get out of my own head.","p":"Read fiction by someone whose life shares almost nothing with yours.","k":["literature","empathy","fiction","perspective"],"src":"After Adichie on fiction and empathy"},
  {"id":"adichie-08","au":"adichie","s":"Story & Voice","a":"I'd rather be disliked for what I actually said than approved of for what I softened.","p":"Say the unsoftened version once today.","k":["directness","approval","courage","honesty"],"src":"After Adichie on speaking plainly"},
  {"id":"peterson-01","au":"peterson","s":"Responsibility & Meaning","a":"Meaning turns up where I pick up a load nobody obliged me to carry.","p":"Take on one responsibility today that nobody assigned to you.","k":["responsibility","meaning","burden","voluntary"],"src":"After 12 Rules for Life and Beyond Order on voluntarily adopted responsibility"},
  {"id":"peterson-02","au":"peterson","s":"Responsibility & Meaning","a":"I forfeit the right to indict the world while the corner of it I actually control is still a mess.","p":"Put one thing in your own domain in order before offering an opinion on a larger one.","k":["order","criticism","humility","scope"],"src":"After 12 Rules for Life, Rule 6 on ordering what is within reach"},
  {"id":"peterson-03","au":"peterson","s":"Responsibility & Meaning","a":"The only comparison that tells me anything is with the person I was a year ago — everyone else is running a different race.","p":"Measure today against your own previous version rather than against anybody's current one.","k":["comparison","progress","self","measurement"],"src":"After 12 Rules for Life, Rule 4 on comparison"},
  {"id":"peterson-04","au":"peterson","s":"Responsibility & Meaning","a":"Every convenient falsehood rearranges the ground I will have to stand on later.","p":"Catch one small untruth you were about to tell, and decline to tell it.","k":["truth","deception","integrity","speech"],"src":"After 12 Rules for Life, Rule 8 on truthful speech"},
  {"id":"peterson-05","au":"peterson","s":"Responsibility & Meaning","a":"I owe myself the care I would obviously extend to someone placed in my charge.","p":"Do one thing for yourself that you would insist on for a person you were looking after.","k":["self-care","responsibility","charge","regard"],"src":"After 12 Rules for Life, Rule 2 on self-regard as an obligation"},
  {"id":"peterson-06","au":"peterson","s":"Responsibility & Meaning","a":"I do my best work with one foot in what I have already mastered and one in what I don't yet understand.","p":"Add one unfamiliar element to a routine you can now perform without thinking.","k":["order","chaos","edge","growth"],"src":"After Maps of Meaning on the border between order and chaos"},
  {"id":"peterson-07","au":"peterson","s":"Responsibility & Meaning","a":"I listen on the working assumption that the other person knows something I need.","p":"In one conversation today, put the other side's case well enough that they'd endorse your version, before making your own.","k":["listening","assumption","conversation","learning"],"src":"After 12 Rules for Life, Rule 9 on listening"},
  {"id":"peterson-08","au":"peterson","s":"Responsibility & Meaning","a":"A vague dread stays enormous; specified precisely it becomes a problem with edges, and problems with edges can be worked on.","p":"Write down exactly what is wrong, in particular words, instead of carrying the general weight of it.","k":["precision","speech","naming","clarity"],"src":"After 12 Rules for Life, Rule 10 on precision in speech"},
  {"id":"voss-01","au":"voss","s":"Negotiation & Listening","a":"Understanding what the other side feels is not conceding it; it is the only thing that ever moves it.","p":"Before arguing your position, state theirs until they would sign off on your version of it.","k":["tactical empathy","understanding","perspective","persuasion"],"src":"After Never Split the Difference on tactical empathy"},
  {"id":"voss-02","au":"voss","s":"Negotiation & Listening","a":"Naming the emotion in the room out loud takes most of the charge out of it.","p":"Offer one sentence beginning “it seems like” where you would normally have asked a question.","k":["labelling","emotion","defusing","naming"],"src":"After Never Split the Difference on labelling"},
  {"id":"voss-03","au":"voss","s":"Negotiation & Listening","a":"Repeating someone's last few words back keeps them talking, and what comes next is usually the part I needed.","p":"Mirror the final three words of something someone says today, then say nothing at all.","k":["mirroring","silence","elaboration","listening"],"src":"After Never Split the Difference on mirroring"},
  {"id":"voss-04","au":"voss","s":"Negotiation & Listening","a":"A refusal is where the conversation starts, not where it ends — it tells me the other side still feels safe enough to be honest.","p":"Frame one question today so a comfortable no is an easy answer, rather than cornering someone into yes.","k":["no","safety","questions","openings"],"src":"After Never Split the Difference on no-oriented questions"},
  {"id":"voss-05","au":"voss","s":"Negotiation & Listening","a":"Being told I am right usually ends the conversation; hearing that I have finally described someone accurately is the thing that opens it.","p":"Summarise a position until the other person confirms you have it, rather than settling for their agreement.","k":["understanding","agreement","summary","confirmation"],"src":"After Never Split the Difference on the difference between agreement and being understood"},
  {"id":"voss-06","au":"voss","s":"Negotiation & Listening","a":"Asking how I am supposed to manage that hands the problem back without a word of refusal.","p":"Replace one flat no today with an open question beginning how or what.","k":["calibrated questions","how","refusal","collaboration"],"src":"After Never Split the Difference on calibrated questions"},
  {"id":"voss-07","au":"voss","s":"Negotiation & Listening","a":"Meeting in the middle can leave two people equally badly served; walking away is a better outcome than agreeing to something that doesn't work.","p":"Name your walk-away point before the conversation begins, and hold it when it arrives.","k":["compromise","walk-away","deals","resolve"],"src":"After Never Split the Difference on the cost of splitting the difference"},
  {"id":"voss-08","au":"voss","s":"Negotiation & Listening","a":"I say the worst thing they could accuse me of before they can, and it stops being ammunition.","p":"Open one difficult conversation by naming the objection you are most dreading.","k":["accusation audit","pre-emption","objections","candour"],"src":"After Never Split the Difference on the accusation audit"}
];
